+                    : super.getLineLeft(metrics);
+        }
+        @Override
+        protected float getLineRight(final LineMetrics metrics) {
+            return getLayout() != null ? getLayout().getLineRight(metrics.line)
+                    : super.getLineRight(metrics);
+        }
+    }
