+
+    private static void clipOutRectCompat(final Canvas canvas, final RectF rect) {
+        if (Build.VERSION.SDK_INT >= 26) {
+            canvas.clipOutRect(rect);
+        } else {
+            canvas.clipRect(rect, android.graphics.Region.Op.DIFFERENCE);
+        }
+    }
