+                        break;
+                    case LINE_START_EDGE:
+                        if (isLTR) {
+                            t.setValue(0);
+                        } else {
+                            getParam(cache, WIDTH, t);
+                        }
+                        break;
+                    case LINE_END_EDGE:
+                        t.get(isLTR ? LINE_RIGHT : LINE_LEFT);
+                        break;
+                    default:
+                        t.resolved(false);
+                        continue;
+                }
+                t.resolved(true);
+            }
+        }
