+    // resolver 2 (fallback): directly from source (by calling respective Layout functions)
+    private static void resolveFromLayout(@NonNull final LayoutTicket t,
+                                          @Nullable final Consumer<LayoutTicket> resolveTo,
+                                          final int... params) {
