+                    debug ? EllipsizeParams.EB_RIGHT_D : EllipsizeParams.EB_RIGHT);
+            final float clipOutBoundsB = getConfigFloat(
+                    debug ? EllipsizeParams.EB_BOTTOM_D : EllipsizeParams.EB_BOTTOM);
