+        int BOOLEAN = 0;
+        int INT = 1;
+        int FLOAT = 2;
+    }
+
+    @Retention(RetentionPolicy.SOURCE)
+    @IntDef({Op.NORMAL, Op.ADD, Op.MINUS})
+    public @interface Op {
