+    public static final int LINE_START = 7 + LINEMETRICS_START;
+    public static final int LINE_END = 8 + LINEMETRICS_START;
+    /* keep this to last */
+    public static final int LINEMETRICS_END = 9 + LINEMETRICS_START;
