+            t.resolved(false);
+            return;
+        }
+        switch (t.getType()) {
+            case ValueType.FLOAT:
+                setParamFloat(cache, t.getParam(), t.asFloat());
+                break;
+            case ValueType.INT:
+                setParamInt(cache, t.getParam(), t.asInt());
+                break;
+            case ValueType.BOOLEAN:
+                setFlag(cache, t.getParam(), t.asBoolean());
+                break;
+            default:
+                t.resolved(false);
+                return;
+        }
+        t.resolved(true);
+    };
