-                            value = Float.floatToRawIntBits(asFloat() + (op == Op.MINUS ? -v : v));
-                        } else {
-                            value = Float.floatToRawIntBits(value + (op == Op.MINUS ? -v : v));
-                            type = ValueType.FLOAT;
-                        }
-                        break;
-                    default:
-                        value = Float.floatToRawIntBits(v);
-                        type = ValueType.FLOAT;
-                        break;
-                }
-            }
